style.css:
@-moz-document domain("roblox.com") {
/* Background Image */
  body {
    background-image: url("https://imgur.com/gallery/halloween-ioTRGIQ"); /* Replace with your image URL */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: #eaeaea !important;
    font-family: Arial, sans-serif;
  }

  /* Add a semi-transparent overlay for readability */
  body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.5); /* Adjust transparency */
    z-index: -1;
  }

  /* Navbar Styling */
  .navbar, .navigation-bar {
    background-color: rgba(15, 52, 96, 0.8) !important; /* Semi-transparent */
    border-bottom: 2px solid #e94560 !important;
  }

  .navbar a, .navigation-bar a {
    color: #ffffff !important;
  }

  .navbar a:hover, .navigation-bar a:hover {
    color: #f5c7b8 !important;
  }

  /* Transparent Cards */
  .card, .game-card, .group-card, .container {
    background-color: rgba(22, 33, 62, 0.8) !important; /* Semi-transparent */
    border: 1px solid #0f3460 !important;
    border-radius: 10px !important;
    color: #ffffff !important;
    padding: 10px;
  }

  /* Buttons */
  button {
    background-color: #e94560 !important;
    color: #ffffff !important;
    border: none;
    border-radius: 5px;
    padding: 10px;
  }

  button:hover {
    background-color: #f37272 !important;
  }

  /* Inputs and Text Areas */
  input, textarea {
    background-color: rgba(255, 255, 255, 0.2) !important; /* Semi-transparent */
    color: #ffffff !important;
    border: 1px solid #e94560 !important;
    border-radius: 5px;
  }

  /* Links */
  a {
    color: #e94560 !important;
    text-decoration: none;
  }

  a:hover {
    color: #f37272 !important;
  }

  /* Footer Styling */
  footer {
    background-color: rgba(15, 52, 96, 0.8) !important; /* Semi-transparent */
    color: #ffffff !important;
    padding: 20px;
  }

  /* Replace Roblox Logo */
  .navbar-brand img, .header-logo img {
    content: url("https://example.com/your-logo.png") !important; /* Replace with your logo URL */
    width: 150px; /* Adjust size */
    height: auto;
  }

  /* Optional: Customize Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #e94560;
    border-radius: 5px;
  }

  ::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2);
  }
}
